package mach;

import mach.cli.Main;
import mach.frontend.Diagnostic;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.*;

/** Contracts of already specified library operations, exercised through generated bytecode. */
class StandardLibraryTest {
    @TempDir Path temp;

    private String run(String source) throws Exception {
        byte[] code = new Compiler().compile("library.ma", source, "LibraryProgram");
        Class<?> program = new ClassLoader(getClass().getClassLoader()) {
            Class<?> loadProgram() { return defineClass("LibraryProgram", code, 0, code.length); }
        }.loadProgram();
        var output = new ByteArrayOutputStream();
        PrintStream previous = System.out;
        try {
            System.setOut(new PrintStream(output, true, StandardCharsets.UTF_8));
            program.getMethod("main", String[].class).invoke(null, (Object) new String[0]);
        } finally {
            System.setOut(previous);
        }
        return output.toString(StandardCharsets.UTF_8).replace("\r\n", "\n");
    }

    private void rejectsPlainValue(String source) {
        Diagnostic error = assertThrows(Diagnostic.class, () -> new Compiler().check("library-invalid.ma", source));
        assertEquals("M2101", error.code(), error.getMessage());
    }

    @Test void strictObjectGetReturnsPresentValue() throws Exception {
        assertEquals("42\n", run("""
            let info = #{age: 42}
            show ((info) get #age) rescue |failure| { 0 }
            """));
    }

    @Test void strictObjectGetMissingIsRecoverableFailure() throws Exception {
        assertEquals("fallback\n", run("""
            let info = #{name: "Adrian"}
            show ((info) get #missing) rescue |failure| { "fallback" }
            """));
    }

    @Test void getElementUsesTheSameStrictKeyContract() throws Exception {
        assertEquals("Adrian\n", run("""
            let info = #{name: "Adrian"}
            show ((info) get_element #name) rescue |failure| { "fallback" }
            """));
    }

    @Test void maybeGetMissingUsesNilFallback() throws Exception {
        assertEquals("default\n", run("""
            let info = #{name: "Adrian"}
            show ((info) maybe_get #missing) ?: "default"
            """));
    }

    @Test void maybeGetKeepsPresentValue() throws Exception {
        assertEquals("Adrian\n", run("""
            let info = #{name: "Adrian"}
            show ((info) maybe_get #name) ?: "default"
            """));
    }

    @Test void safeObjectAccessTreatsMissingAndExplicitNilAsAbsence() throws Exception {
        assertEquals("missing\nempty\n", run("""
            let info = #{port: nil}
            show info's #missing ?: "missing"
            show info's #port ?: "empty"
            """));
    }

    @Test void objectMembershipDistinguishesKeyAndValue() throws Exception {
        assertEquals("true\nfalse\ntrue\nfalse\n", run("""
            let info = #{name: "Adrian", age: 29}
            show (info) has_key? #name
            show (info) has_key? #missing
            show (info) has_value? "Adrian"
            show (info) has_value? "missing"
            """));
    }

    @Test void vectorElementAtReturnsIndexedElement() throws Exception {
        assertEquals("10\n", run("""
            let values = [10, 20, 30]
            show ((values) element_at 1) rescue |failure| { 0 }
            """));
    }

    @Test void vectorNegativeIndexIsRejected() throws Exception {
        assertEquals("0\n", run("""
            let values = [10, 20, 30]
            show ((values) element_at -1) rescue |failure| { 0 }
            """));
    }

    @Test void vectorOutOfBoundsIsRecoverableFailure() throws Exception {
        assertEquals("-1\n-2\n", run("""
            let values = [10, 20, 30]
            show ((values) element_at 4) rescue |failure| { -1 }
            show ((values) element_at -4) rescue |failure| { -2 }
            """));
    }

    @Test void emptyVectorElementAtIsRecoverableFailure() throws Exception {
        assertEquals("empty\n", run("""
            let values = []
            show ((values) element_at 0) rescue |failure| { "empty" }
            """));
    }

    @Test void strictGetCannotBeAssignedDirectlyToPlainType() {
        rejectsPlainValue("let info = #{age: 42}\nlet age int = (info) get #age");
    }

    @Test void elementAtCannotBeAssignedDirectlyToPlainType() {
        rejectsPlainValue("let values = [42]\nlet value int = (values) element_at 0");
    }

    @Test void lengthsAndStringCaseMessages() throws Exception {
        assertEquals("MACHONE\nmachone\n7\n3\n0\n", run("""
            show ("MachOne") upcase
            show ("MachOne") downcase
            show ("MachOne") length
            show ([1, 2, 3]) length
            show ([]) length
            """));
    }

    @Test void failurePredicatesDoNotConfuseNilWithFail() throws Exception {
        assertEquals("true\nfalse\ntrue\nfalse\nfalse\n", run("""
            let failure = (Fail) raise #invalid, "invalid input"
            show (failure) fail?
            show (failure) ok?
            show (42) ok?
            show (42) fail?
            show (nil) fail?
            failure rescue |reason| { nil }
            """));
    }

    @Test void readAndShowWorkInAnExecutableJar() throws Exception {
        Path source = temp.resolve("greet.ma");
        Files.writeString(source, "final name = read \"Name: \"\nshow \"Hello, $name!\"\n");
        assertEquals(0, Main.execute(new String[]{"build", source.toString()}));
        Process process = new ProcessBuilder(
            Path.of(System.getProperty("java.home"), "bin", "java").toString(),
            "-Xverify:all", "-jar", temp.resolve("greet.jar").toString()
        ).redirectErrorStream(true).start();
        try (var input = process.getOutputStream()) {
            input.write("Adrian\n".getBytes(StandardCharsets.UTF_8));
        }
        boolean completed = process.waitFor(15, TimeUnit.SECONDS);
        if (!completed) process.destroyForcibly();
        assertTrue(completed, "I/O program did not terminate after one input line");
        String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8).replace("\r\n", "\n");
        assertEquals(0, process.exitValue(), output);
        assertEquals("Name: Hello, Adrian!\n", output);
    }
}
